/-- For [the specified alphabet-size sequence](hyp:dseq), the [bounded-alphabet sequence is an alphabet-size sequence that remains uniformly bounded asymptotically](goal). -/
def BoundedAlphabetSequence (dseq : ℕ → ℕ) : Prop :=
  IsBigO atTop (fun n => (dseq n : ℝ)) (fun _ => (1 : ℝ))

/-- For [the specified alphabet size, overlap level](hyp:d,epsilon), the [causal model law is a potential-outcome law belonging to the causal completion class at the chosen overlap level](goal). -/
abbrev CausalModelLaw (d : ℕ) (epsilon : ℝ) :=
  {Q : PotentialLaw d // CausalCompletionClass epsilon Q}

/-- Observed outcomes equal the selected potential outcome almost surely. -/
def Consistency {d : ℕ} (Q : PotentialLaw d) : Prop :=
  ∀ z, z.2.2.1 ≠ (if z.2.1 then z.2.2.2.2 else z.2.2.2.1) → fullMass Q z = 0

/-- For [the specified alphabet size](hyp:d), the [dense contrast is a coordinate vector whose alphabet has at least two cells and whose entries all lie between minus one half and one half](goal). -/
abbrev DenseContrast (d : ℕ) :=
  {theta : Fin d → ℝ // 2 ≤ d ∧ ∀ x, theta x ∈ Set.Icc (-1 / 2) (1 / 2)}

/-- For [the specified alphabet size](hyp:d), the [dense Poisson estimator is a measurable real-valued statistic of the dense Poisson sample](goal). -/
abbrev DensePoissonEstimator (d : ℕ) :=
  {f : DensePoissonSample d → ℝ // Measurable f}

/-- For [the specified sample size, alphabet size](hyp:n,d), the [fixed-sample L1 estimator is a measurable real-valued statistic of paired categorical samples](goal). -/
abbrev FixedL1Estimator (n d : ℕ) :=
  {f : (Fin n → (Fin d × Fin d)) → ℝ // Measurable f}

/-- The supplied sample law equals the canonical product law. -/
def IidSampling {d n : ℕ} (P : DiscreteLaw d)
    (mu_n : Measure (Fin n → Obs d)) : Prop := mu_n = productLaw P n

/-- For [the specified alphabet size](hyp:d), the [Poissonized L1 estimator is a measurable real-valued statistic of two categorical histograms](goal). -/
abbrev L1Estimator (d : ℕ) :=
  {f : ((Fin d → ℕ) × (Fin d → ℕ)) → ℝ // Measurable f}

/-- Observed laws packaged with model-class membership. -/
abbrev ModelLaw (d : ℕ) (epsilon : ℝ) :=
  {P : DiscreteLaw d // ObservedModelClass epsilon P}

/-- For [the specified alphabet size](hyp:d), the [probability simplex consists of nonnegative weights on the alphabet that sum to one](goal). -/
def ProbabilitySimplex (d : ℕ) :=
  {R : Fin d → ℝ // (∀ x, 0 ≤ R x) ∧ ∑ x, R x = 1}

