/-- A single paired draw is randomized into one of the four displayed observed atoms. -/
noncomputable def l1SingleKernel {d : ℕ} : ProbabilityTheory.Kernel (Fin d × Fin d) (Obs d) :=
  ProbabilityTheory.Kernel.ofFunOfCountable fun z =>
    (PMF.map (fun k : Fin 4 =>
      if k = 0 then (z.1, false, false)
      else if k = 1 then (z.1, true, true)
      else if k = 2 then (z.2, false, true)
      else (z.2, true, false)) (PMF.uniformOfFintype (Fin 4))).toMeasure

/-- [the stated l1 kernel singleton relation holds](goal). -/
lemma l1_kernel_singleton {d : ℕ} (z : Fin d × Fin d) (o : Obs d) :
    l1SingleKernel z {o} =
      (PMF.map (fun k : Fin 4 =>
        if k = 0 then (z.1, false, false)
        else if k = 1 then (z.1, true, true)
        else if k = 2 then (z.2, false, true)
        else (z.2, true, false)) (PMF.uniformOfFintype (Fin 4))) o := by
  unfold l1SingleKernel
  exact PMF.toMeasure_apply_singleton _ _ (measurableSet_singleton _)

/-- Nonnegative four-vectors whose treated mass is in the overlap band. -/
def overlapCone (epsilon : ℝ) : Set (Cell → ℝ) :=
  {u | (∀ j, 0 ≤ u j) ∧
    epsilon * vectorMass u ≤ vectorArmMass u 1 ∧
    vectorArmMass u 1 ≤ (1 - epsilon) * vectorMass u}

/-- For [the specified observed sample, cell, treatment arm](hyp:sample,x,a), the [sample arm count is the number of observations in the specified cell and treatment arm](goal). -/
def sampleArmCount {n d : ℕ} (sample : Fin n → Obs d) (x : Fin d) (a : Bool) : ℕ :=
  ∑ i, if (sample i).1 = x ∧ (sample i).2.1 = a then 1 else 0

/-- For [the specified observed sample, cell](hyp:sample,x), the [sample cell count is the number of observations in the specified alphabet cell](goal). -/
def sampleCellCount {n d : ℕ} (sample : Fin n → Obs d) (x : Fin d) : ℕ :=
  ∑ i, if (sample i).1 = x then 1 else 0

/-- For [the specified observed sample, cell, treatment arm](hyp:sample,x,a), the [sample success count is the number of successful observations in the specified cell and treatment arm](goal). -/
def sampleSuccessCount {n d : ℕ} (sample : Fin n → Obs d) (x : Fin d) (a : Bool) : ℕ :=
  ∑ i, if (sample i).1 = x ∧ (sample i).2.1 = a ∧ (sample i).2.2 then 1 else 0

/-- For [the specified overlap level](hyp:epsilon), the [sharp-overlap-constant question asks whether the normalized nonsaturated minimax risk converges to a positive finite limit and whether the sharp-constant program yields an attaining estimator](goal). -/
def sharpOverlapConstantQuestion (epsilon : ℝ) : _root_.String :=
  "Along nonsaturated sequences d tending to infinity with d/(n log(ed)) tending to zero, does (n log(ed)/d) times the minimax risk converge to a finite positive limit, and is an estimator attaining it derivable through the sharp-constant handle? The matched frontier proves only positive finite liminf/limsup bounds; it asserts neither convergence, a cone-dependent optimal leading constant, nor an attaining estimator."
